// Items cuyo último paso falló por Gemini (503 o cuota) y ya pasó la espera. WF20 vuelve a correr el encadenado completo
const MIN_AGE_MIN = { gemini_http: 15, waiting_quota: 240 }; // la cuota gratuita se reinicia a medianoche del Pacífico
const MAX_ATTEMPTS = 3; // intentos totales por paso (contados en pipeline_steps)
const MAX_PER_RUN = 5;
const base = `${$env.SUPABASE_URL}/rest/v1`;
const key = $env.SUPABASE_SERVICE_ROLE_KEY;
const headers = { apikey: key, Authorization: `Bearer ${key}` };
const get = (path, qs) => this.helpers.httpRequest({ method: 'GET', url: `${base}/${path}`, headers, json: true, qs });

const steps = await get('pipeline_steps', {
  select: 'content_item_id,step,attempt,status,error_type,started_at,finished_at',
  status: 'in.(failed,waiting_quota)', error_type: 'in.(gemini_http,waiting_quota)',
  started_at: `gte.${new Date(Date.now() - 48 * 3600e3).toISOString()}`, order: 'started_at.desc', limit: 500,
});
// El último intento de cada item decide: si un paso posterior tuvo éxito, ya no hay nada que retomar
const latestByItem = new Map();
for (const s of steps) if (!latestByItem.has(s.content_item_id)) latestByItem.set(s.content_item_id, s);
const due = [...latestByItem.values()].filter((s) =>
  s.attempt < MAX_ATTEMPTS && Date.now() - Date.parse(s.finished_at) >= (MIN_AGE_MIN[s.error_type] ?? Infinity) * 60e3);
if (due.length === 0) return [];

const items = await get('content_items', {
  select: 'id,raw_asset_url,notes,status', id: `in.(${due.map((s) => s.content_item_id).join(',')})`, status: 'eq.processing',
});
return items.filter((i) => i.raw_asset_url).slice(0, MAX_PER_RUN)
  .map((i) => ({ json: { content_item_id: i.id, image_url: i.raw_asset_url, notes: i.notes ?? '' } }));
